import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage({viewport:{width:1280,height:900}});
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(800);
await p.goto('http://127.0.0.1:54569/pipeline');
await p.waitForTimeout(500);
const names = () => p.$$eval('#pl .nm', n=>n.map(x=>x.textContent));
async function drag(from, to){ // to: target name, move to its position
  const hs = await p.$$('#pl li');
  let src=null, dst=null;
  for (const li of hs){ const t=await li.$eval('.nm',n=>n.textContent); if(t===from) src=li; if(t===to) dst=li; }
  const h = await src.$('.h'); const hb = await h.boundingBox();
  const db = await dst.boundingBox();
  await p.mouse.move(hb.x+hb.width/2, hb.y+hb.height/2);
  await p.mouse.down();
  const ty = db.y + db.height/2 - 2;
  await p.mouse.move(hb.x+hb.width/2, ty, {steps:20});
  await p.mouse.up();
  await p.waitForTimeout(200);
}
await drag('Picking','Invoicing');
console.log(await names());
await drag('Quality check','Credit check');
console.log(await names());
await p.click('#save');
await p.waitForTimeout(500);
console.log(await p.textContent('#done'));
await p.reload(); await p.waitForTimeout(500);
console.log(await names());
await b.close();
EOF
